<?php
declare(strict_types=1);

const LC_ROOT = __DIR__ . '/..';
foreach ([LC_ROOT.'/.env', dirname(LC_ROOT).'/.env'] as $env) if (is_file($env)) foreach (file($env, FILE_IGNORE_NEW_LINES) as $line) if (preg_match('/^([A-Z][A-Z0-9_]*)=(.*)$/', trim($line), $m) && getenv($m[1])===false) putenv($m[1].'='.trim(trim($m[2]), "\"'"));
function lc_env(string $key,string $default=''): string { $value=getenv($key); return $value===false||$value===''?$default:$value; }
function lc_db(): PDO { static $db; if(!$db){$path=lc_env('LICENSE_DB_PATH',LC_ROOT.'/storage/licenses.sqlite'); if(!is_dir(dirname($path))) mkdir(dirname($path),0700,true); $db=new PDO('sqlite:'.$path,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); $db->exec('PRAGMA foreign_keys=ON; PRAGMA busy_timeout=5000');} return $db; }
function q(string $sql,array $args=[]): PDOStatement{$s=lc_db()->prepare($sql);$s->execute($args);return $s;}
function one(string $sql,array $args=[]):?array{return q($sql,$args)->fetch()?:null;}
function esc(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function csrf():string{if(session_status()!==PHP_SESSION_ACTIVE)session_start();return $_SESSION['csrf']??=bin2hex(random_bytes(24));}
function require_csrf():void{if(!hash_equals($_SESSION['csrf']??'',(string)($_POST['csrf']??'')))throw new RuntimeException('Invalid request token');}
function setup():void{lc_db()->exec("CREATE TABLE IF NOT EXISTS admins(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS themes(id INTEGER PRIMARY KEY,name TEXT NOT NULL,locale TEXT NOT NULL DEFAULT 'global',payload TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL CHECK(status IN('draft','published')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS licenses(id INTEGER PRIMARY KEY,product TEXT NOT NULL DEFAULT 'transport-cms',key_hash TEXT NOT NULL,key_hint TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','suspended','revoked')),domain_limit INTEGER NOT NULL DEFAULT 1,theme_id INTEGER REFERENCES themes(id) ON DELETE SET NULL,source TEXT NOT NULL DEFAULT 'manual',purchase_code_hash TEXT UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS domains(id INTEGER PRIMARY KEY,license_id INTEGER NOT NULL REFERENCES licenses(id) ON DELETE CASCADE,domain TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at TEXT,UNIQUE(license_id,domain)); CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,license_id INTEGER REFERENCES licenses(id) ON DELETE SET NULL,action TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS purchase_requests(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,company TEXT NOT NULL DEFAULT '',message TEXT NOT NULL DEFAULT '',product TEXT NOT NULL DEFAULT 'transport-cms',status TEXT NOT NULL DEFAULT 'new' CHECK(status IN('new','contacted','completed','closed')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)");}
function host(string $value):string{$value=strtolower(trim($value));$value=preg_replace('#^https?://#','',$value);$value=explode('/',$value,2)[0];$value=preg_replace('/:\d+$/','',$value);if(!preg_match('/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/',$value))throw new RuntimeException('A valid public domain is required.');return $value;}
function key_parts(string $key):array{if(!preg_match('/^TDL-([0-9]+)-([A-Z0-9]{24})$/',strtoupper(trim($key)),$m))throw new RuntimeException('Invalid licence key format.');return [(int)$m[1],strtoupper($m[2])];}
function issue_key():array{$secret=strtoupper(bin2hex(random_bytes(12)));$id=(int)lc_db()->lastInsertId();return [$id,'TDL-'.$id.'-'.$secret,$secret];}
function api_json():array{$raw=file_get_contents('php://input')?:'';$json=json_decode($raw,true);return is_array($json)?$json:$_POST;}
function reply(array $data,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_SLASHES);exit;}
function licence_api(bool $activate):never{try{$input=api_json();[$id,$secret]=key_parts((string)($input['license_key']??''));$licence=one('SELECT * FROM licenses WHERE id=?',[$id]);if(!$licence||!password_verify($secret,$licence['key_hash'])||$licence['status']!=='active')throw new RuntimeException('Licence is not active.');$domain=host((string)($input['domain']??''));$bound=one('SELECT id FROM domains WHERE license_id=? AND domain=?',[$id,$domain]);if(!$bound){$count=(int)(one('SELECT count(*) count FROM domains WHERE license_id=?',[$id])['count']??0);if(!$activate||$count>=(int)$licence['domain_limit'])throw new RuntimeException('This domain is not permitted for the licence.');q('INSERT INTO domains(license_id,domain,last_seen_at) VALUES(?,?,datetime(\'now\'))',[$id,$domain]);q('INSERT INTO events(license_id,action,detail) VALUES(?,?,?)',[$id,'domain.activated',$domain]);}else q('UPDATE domains SET last_seen_at=datetime(\'now\') WHERE id=?',[$bound['id']]);$locale=preg_replace('/[^a-z-]/','',strtolower((string)($input['locale']??'global')));$theme=one("SELECT name,locale,payload FROM themes WHERE id=? AND status='published' AND locale IN (?, 'global') ORDER BY locale=? DESC LIMIT 1",[$licence['theme_id'],$locale,$locale]);reply(['active'=>true,'license'=>['product'=>$licence['product'],'domain'=>$domain,'domain_limit'=>(int)$licence['domain_limit']],'theme'=>$theme?['name'=>$theme['name'],'locale'=>$theme['locale'],'payload'=>json_decode($theme['payload'],true)]:null,'checked_at'=>gmdate('c')]);}catch(Throwable $e){reply(['active'=>false,'error'=>$e->getMessage()],422);}}
function logged_in():bool{return !empty($_SESSION['admin']);}
function login_required():void{if(!logged_in()){header('Location: ./login');exit;}}
function layout(string $title,string $body):never{echo '<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.esc($title).' · TofiDesk</title><style>body{font:16px system-ui;margin:0;background:#f3f6f8;color:#102a3a}main{max-width:1060px;margin:40px auto;padding:0 20px}.card{background:#fff;padding:24px;border-radius:12px;margin:16px 0;box-shadow:0 2px 12px #102a3a12}input,textarea,select{width:100%;box-sizing:border-box;padding:10px;margin:5px 0 12px}button{background:#ff7b28;color:#fff;border:0;padding:11px 16px;border-radius:7px;font-weight:700}a{color:#0b6d86}table{width:100%;border-collapse:collapse}td,th{padding:9px;text-align:left;border-bottom:1px solid #ddd}.nav{display:flex;gap:16px;align-items:center}</style><main><div class="nav"><h1>TofiDesk Transportation</h1><a href="./">Dashboard</a><a href="./themes">Themes</a><a href="./licenses">Licences</a><a href="./logout">Sign out</a></div>'.$body.'</main>';exit;}
setup();$sessionPath=dirname(lc_env('LICENSE_DB_PATH',LC_ROOT.'/storage/licenses.sqlite')).'/sessions';if(!is_dir($sessionPath))mkdir($sessionPath,0700,true);session_save_path($sessionPath);session_start();$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';$script=$_SERVER['SCRIPT_NAME']??'/index.php';$base=str_ends_with($script,'/index.php')?rtrim(dirname($script),'/'):'';if($base!==''&&$base!=='/'&&str_starts_with($path,$base))$path=substr($path,strlen($base))?:'/';
if($path==='/api/v1/licenses/activate')licence_api(true);if($path==='/api/v1/licenses/check')licence_api(false);
if($path==='/shop'){ $themes=q("SELECT name,locale FROM themes WHERE status='published' ORDER BY id DESC LIMIT 12")->fetchAll(); $cards=''; foreach($themes as $theme)$cards.='<li><strong>'.esc($theme['name']).'</strong> · '.esc($theme['locale']==='global'?'All languages':strtoupper($theme['locale'])).'</li>'; layout('Transport CMS','<div class="card"><h2>Transport CMS</h2><p>A multilingual transport-business website and administration platform with quotation forms, appointment workflow, gallery, SEO, 14 built-in languages and licence-controlled theme delivery.</p><p><a href="./contact">Request purchase and demo access →</a></p></div><div class="card"><h2>Published themes</h2><ul>'.$cards.'</ul><p>Themes are assigned to licences and delivered as safe design data to installed sites.</p></div><div class="card"><h2>For buyers</h2><p>After purchase, enter the issued licence key in the product’s Licence panel and activate the installation domain.</p></div>'); }
if($path==='/contact'){ $notice=''; if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$name=trim((string)($_POST['name']??''));$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$company=mb_substr(trim((string)($_POST['company']??'')),0,160);$message=mb_substr(trim((string)($_POST['message']??'')),0,3000);if($name===''||!$email)throw new RuntimeException('Name and a valid email are required.');q('INSERT INTO purchase_requests(name,email,company,message) VALUES(?,?,?,?)',[$name,$email,$company,$message]);$notice='<p class="card">Thanks. Your purchase request was recorded and will be answered by email.</p>'; } layout('Contact and purchase',$notice.'<form class="card" method="post"><input type="hidden" name="csrf" value="'.csrf().'"><h2>Purchase or contact request</h2><input name="name" required placeholder="Name"><input type="email" name="email" required placeholder="Email"><input name="company" placeholder="Company"><textarea name="message" placeholder="Tell us about your domain, preferred language and theme"></textarea><button>Send request</button></form>'); }
if($path==='/install'){if(one('SELECT id FROM admins'))layout('Already installed','<div class="card">Installation is locked.</div>');if(!hash_equals(lc_env('LICENSE_INSTALL_TOKEN'),(string)($_GET['token']??'')))reply(['error'=>'Not found'],404);if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$password=(string)($_POST['password']??'');if(!$email||strlen($password)<12)throw new RuntimeException('Use a valid email and 12+ character password.');q('INSERT INTO admins(email,password_hash) VALUES(?,?)',[$email,password_hash($password,PASSWORD_DEFAULT)]);header('Location: ./login');exit;}layout('Install','<form class="card" method="post"><input type="hidden" name="csrf" value="'.csrf().'"><h2>First administrator</h2><input name="email" type="email" required placeholder="Email"><input name="password" type="password" minlength="12" required placeholder="Password"><button>Create administrator</button></form>');}
if($path==='/login'){if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$a=one('SELECT * FROM admins WHERE email=?',[strtolower(trim($_POST['email']??''))]);if($a&&password_verify((string)($_POST['password']??''),$a['password_hash'])){$_SESSION['admin']=$a['id'];header('Location: ./');exit;}}layout('Sign in','<form class="card" method="post"><input type="hidden" name="csrf" value="'.csrf().'"><h2>Administrator sign in</h2><input name="email" type="email" required><input name="password" type="password" required><button>Sign in</button></form>');}
if($path==='/logout'){session_destroy();header('Location: ./login');exit;}login_required();
if($path==='/themes'&&$_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$payload=json_decode((string)($_POST['payload']??''),true);if(!is_array($payload))throw new RuntimeException('Theme payload must be JSON.');q('INSERT INTO themes(name,locale,payload,status) VALUES(?,?,?,?)',[trim($_POST['name']??''),$_POST['locale']??'global',json_encode($payload),$_POST['status']??'draft']);header('Location: ./themes');exit;}
if($path==='/licenses'&&$_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$theme=(int)($_POST['theme_id']??0)?:null;$limit=max(1,min(50,(int)($_POST['domain_limit']??1)));$pending='pending-'.bin2hex(random_bytes(8));q('INSERT INTO licenses(product,key_hash,key_hint,status,domain_limit,theme_id,source) VALUES(?,?,?,?,?,?,?)',['transport-cms','pending',$pending,'active',$limit,$theme,'manual']);[$id,$key,$secret]=issue_key();q('UPDATE licenses SET key_hash=?,key_hint=? WHERE id=?',[password_hash($secret,PASSWORD_DEFAULT),'TDL-'.$id,$id]);$_SESSION['issued_key']=$key;header('Location: ./licenses');exit;}
if($path==='/themes'){$themes=q('SELECT * FROM themes ORDER BY id DESC')->fetchAll();$rows='';foreach($themes as $t)$rows.='<tr><td>'.esc($t['name']).'</td><td>'.esc($t['locale']).'</td><td>'.esc($t['status']).'</td></tr>';layout('Themes','<div class="card"><h2>Publishable themes</h2><p>Only published theme payloads are returned to licensed installations. Payload can contain colours, logo/media URLs and section settings; never include executable PHP.</p><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input name="name" required placeholder="Theme name"><select name="locale"><option value="global">All languages</option><option>tr</option><option>en</option><option>de</option><option>fr</option><option>es</option><option>it</option><option>pt</option><option>nl</option><option>ru</option><option>ar</option><option>zh</option><option>ja</option><option>ko</option><option>fa</option></select><select name="status"><option value="draft">Draft</option><option value="published">Published</option></select><textarea name="payload" required>{"primary_color":"#0D2E42","accent_color":"#FF9149"}</textarea><button>Save theme</button></form></div><div class="card"><table><tr><th>Name</th><th>Locale</th><th>Status</th></tr>'.$rows.'</table></div>');}
if($path==='/licenses'){$themes=q("SELECT id,name FROM themes WHERE status='published' ORDER BY name")->fetchAll();$opts='<option value="">No remote theme</option>';foreach($themes as $t)$opts.='<option value="'.$t['id'].'">'.esc($t['name']).'</option>';$rows='';foreach(q('SELECT l.*,group_concat(d.domain,\', \') domains FROM licenses l LEFT JOIN domains d ON d.license_id=l.id GROUP BY l.id ORDER BY l.id DESC')->fetchAll() as $l)$rows.='<tr><td>'.esc($l['key_hint']).'…</td><td>'.esc($l['status']).'</td><td>'.esc($l['domains']??'—').'</td><td>'.(int)$l['domain_limit'].'</td></tr>';$notice=isset($_SESSION['issued_key'])?'<div class="card"><strong>New licence key — show once:</strong><code>'.esc($_SESSION['issued_key']).'</code></div>':'';unset($_SESSION['issued_key']);$requests='';foreach(q('SELECT * FROM purchase_requests ORDER BY id DESC LIMIT 50')->fetchAll() as $request)$requests.='<tr><td>'.esc($request['name']).'<br><small>'.esc($request['email']).'</small></td><td>'.esc($request['company']).'</td><td>'.esc($request['message']).'</td><td>'.esc($request['status']).'</td></tr>';layout('Licences',$notice.'<div class="card"><h2>Create licence</h2><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><label>Allowed domains</label><input type="number" name="domain_limit" value="1" min="1" max="50"><label>Published remote theme</label><select name="theme_id">'.$opts.'</select><button>Create key</button></form></div><div class="card"><table><tr><th>Key</th><th>Status</th><th>Domains</th><th>Limit</th></tr>'.$rows.'</table></div><div class="card"><h2>Purchase requests</h2><table><tr><th>Buyer</th><th>Company</th><th>Message</th><th>Status</th></tr>'.$requests.'</table></div>');}
$stats=one('SELECT (SELECT count(*) FROM licenses) licences,(SELECT count(*) FROM domains) domains,(SELECT count(*) FROM themes WHERE status=\'published\') themes');layout('Dashboard','<div class="card"><h2>Licence service</h2><p>Active licences: '.(int)$stats['licences'].' · Bound domains: '.(int)$stats['domains'].' · Published themes: '.(int)$stats['themes'].'</p><p>Use the Themes page to publish a signed data-only theme and Licences to issue a domain-limited key.</p></div>');
